```python
import numpy as np

MEAN = np.array([0.485, 0.456, 0.406], dtype=np.float32)
STD = np.array([0.229, 0.224, 0.225], dtype=np.float32)


def preprocess(batch):
    # batch: uint8 array (N, 224, 224, 3)
    x = batch.astype(np.float32) / 255.0
    x = (x - MEAN) / STD
    return np.transpose(x, (0, 3, 1, 2))


def softmax(logits):
    e = np.exp(logits - logits.max(axis=1, keepdims=True))
    return e / e.sum(axis=1, keepdims=True)


def top5_labels(probs, labels):
    results = []
    for row in probs:
        best = np.argsort(row)[::-1][:5]
        out = []
        for i in best:
            out.append({"label": labels[i], "score": round(float(row[i]), 4)})
        results.append(out)
    return results


def classify(session, batch, labels):
    x = preprocess(batch)
    logits = session.run(None, {"input": x})[0]
    probs = softmax(logits)
    return top5_labels(probs, labels)
