```ts
export interface Prediction {
  id: string;
  label: string;
  confidence: number;
  latencyMs: number;
}

const ROW_HEIGHT = 28;
const OVERSCAN = 8;

export function mountPredictionTable(
  container: HTMLElement,
  rows: readonly Prediction[],
): () => void {
  container.style.overflowY = "auto";

  const spacer = document.createElement("div");
  spacer.style.position = "relative";
  spacer.style.height = `${rows.length * ROW_HEIGHT}px`;
  container.replaceChildren(spacer);

  const pool: HTMLDivElement[] = [];
  let rafId = 0;

  function createRow(): HTMLDivElement {
    const el = document.createElement("div");
    el.style.cssText =
      `position:absolute;left:0;right:0;top:0;height:${ROW_HEIGHT}px;` +
      "display:grid;grid-template-columns:2fr 2fr 1fr 1fr;align-items:center";
    for (let c = 0; c < 4; c++) el.appendChild(document.createElement("span"));
    spacer.appendChild(el);
    return el;
  }

  function render(): void {
    rafId = 0;
    const first = Math.max(0, Math.floor(container.scrollTop / ROW_HEIGHT) - OVERSCAN);
    const span = Math.ceil(container.clientHeight / ROW_HEIGHT) + OVERSCAN * 2;
    const count = Math.max(0, Math.min(rows.length - first, span));

    while (pool.length < count) pool.push(createRow());

    for (let i = 0; i < pool.length; i++) {
      const el = pool[i];
      if (i >= count) {
        el.style.display = "none";
        continue;
      }
      const row = rows[first + i];
      const cells = el.children;
      cells[0].textContent = row.id;
      cells[1].textContent = row.label;
      cells[2].textContent = row.confidence.toFixed(3);
      cells[3].textContent = `${row.latencyMs} ms`;
      el.style.display = "grid";
      el.style.transform = `translateY(${(first + i) * ROW_HEIGHT}px)`;
    }
  }

  function onScroll(): void {
    if (rafId === 0) rafId = requestAnimationFrame(render);
  }

  container.addEventListener("scroll", onScroll, { passive: true });
  render();

  return () => {
    container.removeEventListener("scroll", onScroll);
    if (rafId !== 0) cancelAnimationFrame(rafId);
    container.replaceChildren();
  };
}
