Sort the list once, then use binary search to find the first match on every keystroke:

```javascript
function createCityIndex(cities) {
  const entries = cities.map((name) => ({ key: name.toLowerCase(), name }));
  entries.sort((a, b) => (a.key < b.key ? -1 : a.key > b.key ? 1 : 0));
  return entries;
}

function suggestCities(index, typed, limit = 8) {
  const prefix = typed.trim().toLowerCase();
  if (!prefix) return [];

  // first entry whose key is >= prefix
  let lo = 0;
  let hi = index.length;
  while (lo < hi) {
    const mid = (lo + hi) >> 1;
    if (index[mid].key < prefix) lo = mid + 1;
    else hi = mid;
  }

  // all keys with this prefix sit next to each other
  const result = [];
  for (let i = lo; i < index.length && result.length < limit; i++) {
    if (!index[i].key.startsWith(prefix)) break;
    result.push(index[i].name);
  }
  return result;
}
```

