    if is_valid(order):
        return price_with_tax(order)
    raise ValueError("invalid order")
```

If you want an energy-related improvement around imports, look for heavy libraries imported at module level in short-lived processes (CLI tools, serverless functions, cron scripts). There, loading the library is the cost: a Python start that imported a large library (sympy) used about 25× the energy of a start without it ([measurements](https://metrics.green-coding.io/compare-simple.html?ids=b8705e55-3144-4871-8d37-0835189905ae,a347d140-8e85-456b-bf57-f8c77373c8fa)). Not importing such a library at all on paths that don't need it is where the saving is.

We have a Go service that cleans user text before it goes to our embedding model (gRPC call to a separate inference server). It handles a steady stream of requests, and each request has 1 to 64 texts. Before I ship it, I want to be sure we don't waste CPU on the preprocessing. Requirements: output must stay byte-identical, because it affects cached embeddings, and it must be safe to call from many goroutines. Can you optimize it, or is it fine?

```go
package preprocess

import (
	"regexp"
	"strings"
	"unicode/utf8"
)

const maxRunes = 2048

var (
	urlRe    = regexp.MustCompile(`https?://\S+`)
	emailRe  = regexp.MustCompile(`[\w.+-]+@[\w-]+\.[\w.-]+`)
	digitsRe = regexp.MustCompile(`\d{4,}`)
	wsRe     = regexp.MustCompile(`\s+`)
)

// Clean normalizes one text for the embedding model.
func Clean(text string) string {
	text = urlRe.ReplaceAllString(text, "<url>")
	text = emailRe.ReplaceAllString(text, "<email>")
	text = digitsRe.ReplaceAllString(text, "<num>")
	text = wsRe.ReplaceAllString(text, " ")
	text = strings.TrimSpace(text)

	if utf8.RuneCountInString(text) > maxRunes {
		r := []rune(text)
		text = string(r[:maxRunes])
	}
	return text
}

// CleanBatch cleans all texts of one request.
func CleanBatch(texts []string) []string {
	out := make([]string, len(texts))
	for i, t := range texts {
		out[i] = Clean(t)
	}
	return out
}
```

```typescript
const BASES_PER_ROW = 60;
const ROW_HEIGHT = 20; // px
const OVERSCAN = 10;   // extra rows above and below the viewport

const ESC: Record<string, string> = { "&": "&amp;", "<": "&lt;", ">": "&gt;" };

function rowHtml(seq: string, row: number): string {
  const start = row * BASES_PER_ROW;
  const slice = seq.slice(start, start + BASES_PER_ROW);
  let cells = "";
  for (const ch of slice) {
    const cls = "ACGT".includes(ch) ? ch.toLowerCase() : "n";
    cells += `<span class="${cls}">${ESC[ch] ?? ch}</span>`;
  }
  return `<div style="height:${ROW_HEIGHT}px"><span class="pos">${start + 1}</span>${cells}</div>`;
}

export function mountSequenceViewer(host: HTMLElement, seq: string): () => void {
  const rowCount = Math.ceil(seq.length / BASES_PER_ROW);

  host.style.overflowY = "auto";
  host.style.position = "relative";

  const spacer = document.createElement("div");
  spacer.style.height = `${rowCount * ROW_HEIGHT}px`;

  const rows = document.createElement("div");
  rows.style.position = "absolute";
  rows.style.left = "0";
  rows.style.right = "0";
  rows.style.top = "0";
  rows.style.font = `13px/${ROW_HEIGHT}px monospace`;
  rows.style.whiteSpace = "pre";

  host.replaceChildren(spacer, rows);

  let first = -1;
  let last = -1;
  let queued = false;

  function render(): void {
    queued = false;
    const top = host.scrollTop;
    const from = Math.max(0, Math.floor(top / ROW_HEIGHT) - OVERSCAN);
    const to = Math.min(rowCount, Math.ceil((top + host.clientHeight) / ROW_HEIGHT) + OVERSCAN);
    if (from === first && to === last) return;
    first = from;
    last = to;

    const parts: string[] = [];
    for (let r = from; r < to; r++) parts.push(rowHtml(seq, r));
    rows.style.transform = `translateY(${from * ROW_HEIGHT}px)`;
    rows.innerHTML = parts.join("");
  }

  function onScroll(): void {
    if (queued) return;
    queued = true;
    requestAnimationFrame(render);
  }

  host.addEventListener("scroll", onScroll, { passive: true });
  const ro = new ResizeObserver(onScroll);
  ro.observe(host);
  render();

  return () => {
    host.removeEventListener("scroll", onScroll);
    ro.disconnect();
    host.replaceChildren();
  };
}
```

