```go
package calib

import (
	"database/sql"
	"fmt"
	"math"
)

type Point struct {
	RunID  int64
	Channel string
	Raw    float64
	Ref    float64
}

func LoadPoints(db *sql.DB, runID int64) ([]Point, error) {
	rows, err := db.Query("SELECT * FROM calibration_points WHERE run_id = ? ORDER BY raw_value", runID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var pts []Point
	for rows.Next() {
		var p Point
		if err := rows.Scan(&p.RunID, &p.Channel, &p.Raw, &p.Ref); err != nil {
			return nil, err
		}
		pts = append(pts, p)
	}
	return pts, rows.Err()
}

// FitLinear returns slope and intercept of a least-squares line Ref = a*Raw + b.
func FitLinear(pts []Point) (a, b float64, err error) {
	n := float64(len(pts))
	if n < 2 {
		return 0, 0, fmt.Errorf("need at least 2 points, got %d", len(pts))
	}
	var sx, sy, sxx, sxy float64
	for _, p := range pts {
		sx += p.Raw
		sy += p.Ref
		sxx += p.Raw * p.Raw
		sxy += p.Raw * p.Ref
	}
	den := n*sxx - sx*sx
	if math.Abs(den) < 1e-12 {
		return 0, 0, fmt.Errorf("degenerate x values")
	}
	a = (n*sxy - sx*sy) / den
	b = (sy - a*sx) / n
	return a, b, nil
}
