async function fetchCounts(base: string): Promise<Counts> {
  const res = await fetch(`${base}/logs/summary.json`, {
    signal: AbortSignal.timeout(5000), // do not wait forever for a dead server
  });
  if (!res.ok) {
    throw new Error(`HTTP ${res.status}`);
  }
  return (await res.json()) as Counts;
}

async function main(): Promise<void> {
  // All 12 requests start at once, we wait for all of them together.
  const results = await Promise.allSettled(SERVERS.map((s) => fetchCounts(s)));

  const total: Counts = {};
  results.forEach((result, i) => {
    if (result.status === "rejected") {
      console.error(`skipped ${SERVERS[i]}: ${result.reason}`);
      return;
    }
    for (const [level, n] of Object.entries(result.value)) {
      total[level] = (total[level] ?? 0) + n;
    }
  });

  console.log(total);
}

