```javascript
#!/usr/bin/env node
const fs = require('fs');
const { Client } = require('pg');

async function main() {
  const file = process.argv[2];
  const client = new Client({ connectionString: process.env.DATABASE_URL });
  await client.connect();

  const lines = fs.readFileSync(file, 'utf8').split('\n');
  let count = 0;
  for (const line of lines) {
    if (!line.trim()) continue;
    const e = JSON.parse(line);
    await client.query(
      'INSERT INTO access_log (ts, method, path, status, bytes) VALUES ($1, $2, $3, $4, $5)',
      [e.ts, e.method, e.path, e.status, e.bytes]
    );
    count++;
  }
  console.log(`Imported ${count} rows`);
  await client.end();
}

main();
```

**Workload:** script (bulk import, files with hundreds of thousands of lines)

#### [Bug] No transaction, no cleanup, no error handling
- **Where:** the loop, `client.end()` and `main()`
- **Issue:** every INSERT commits on its own. If line 200,000 is bad JSON, 199,999 rows stay in the table and a re-run imports them twice. On an error the connection is never closed, and `main()` has no `.catch`, so you get an unhandled rejection.
- **Fix:** one transaction around the import, `finally` for `client.end()`, and set a non-zero exit code on failure.

#### [High] One round trip and one commit per row
- **Where:** `await client.query('INSERT ...')` inside the loop
- **Issue:** each log line costs a network round trip, a parse/plan step and a commit on the server. The work grows with the number of lines, and the client sits idle while it waits.
- **Fix:** collect rows and send them in batches of a few thousand. Passing one array per column with `unnest` keeps it one statement per batch and avoids the 65,535 parameter limit of multi-row `VALUES`.
- **Impact:** reduces E on client and server, and network chatter. In Green Metrics Tool micro-benchmarks (PostgreSQL 16, psycopg client, 500,000 rows in 5,000-row batches), `COPY` used about 22× less CPU energy than one INSERT per row ([measurements](https://metrics.green-coding.io/compare-simple.html?ids=8e80b599-3332-432f-8c7e-1cfb93a3a354,8b4c205d-5fb1-40af-ab77-0427ca572f4e,adff4e53-2f1a-4d88-9c0d-dd681d02923f)). A batched `unnest` insert will land between the two. With batches of only about 100 rows the differences were small, so keep batches large.

#### [Medium] Whole file read into memory
- **Where:** `fs.readFileSync(file, 'utf8').split('\n')`
- **Issue:** a large log is held in memory twice (string and array). Memory use grows with file size.
- **Fix:** stream the file line by line with `readline`.

```javascript
#!/usr/bin/env node
const fs = require('fs');
const readline = require('readline');
const { Client } = require('pg');

const BATCH_SIZE = 5000;

// Adjust the casts to your column types.
const INSERT_SQL = `
  INSERT INTO access_log (ts, method, path, status, bytes)
  SELECT * FROM unnest($1::timestamptz[], $2::text[], $3::text[], $4::int[], $5::bigint[])`;

async function flush(client, rows) {
  if (rows.length === 0) return;
  await client.query(INSERT_SQL, [
    rows.map((r) => r.ts),
    rows.map((r) => r.method),
    rows.map((r) => r.path),
    rows.map((r) => r.status),
    rows.map((r) => r.bytes),
  ]);
}

async function main() {
  const file = process.argv[2];
  const client = new Client({ connectionString: process.env.DATABASE_URL });
  await client.connect();

  try {
    await client.query('BEGIN');
    const rl = readline.createInterface({
      input: fs.createReadStream(file),
      crlfDelay: Infinity,
    });

    let batch = [];
    let count = 0;
    for await (const line of rl) {
      if (!line.trim()) continue;
      batch.push(JSON.parse(line));
      if (batch.length >= BATCH_SIZE) {
        await flush(client, batch);
        count += batch.length;
        batch = [];
      }
    }
    await flush(client, batch);
    count += batch.length;

    await client.query('COMMIT');
    console.log(`Imported ${count} rows`);
  } catch (err) {
    await client.query('ROLLBACK').catch(() => {});
    console.error(`Import failed, nothing was written: ${err.message}`);
    process.exitCode = 1;
  } finally {
    await client.end();
  }
}

main();
```

**Behavior change:** the import is now all-or-nothing. One bad line rolls back the whole file instead of leaving a partial import. If you prefer partial progress, commit per batch instead.

If the files grow into the millions of lines, `COPY ... FROM STDIN` (with `pg-copy-streams`) is the next step. For a few thousand rows per run, the batched insert above is enough.

This uses PurgeCSS. It scans the built HTML and JS and rewrites each CSS file in place with only the rules that are used.

```javascript
// scripts/purge-css.mjs
import { PurgeCSS } from 'purgecss';
import { writeFile } from 'node:fs/promises';

const dist = process.argv[2] ?? 'dist';

const results = await new PurgeCSS().purge({
  content: [`${dist}/**/*.html`, `${dist}/**/*.js`],
  css: [`${dist}/**/*.css`],
  // Classes that are added at runtime and never appear as full strings in the source.
  safelist: {
    standard: ['show', 'active', 'is-open', 'fade', 'collapse', 'collapsing'],
    greedy: [/^modal/, /^tooltip/],
  },
  keyframes: true,
  fontFace: true,
  variables: true,
});

for (const { file, css } of results) {
  await writeFile(file, css);
}

console.log(`Purged ${results.length} CSS file(s) in ${dist}/`);
```

Run it as the last build step, after bundling and before any minify or compress step:

```json
{
  "scripts": {
    "build": "vite build && node scripts/purge-css.mjs dist"
  }
}
```

**Green Notes**
- **Remove unused CSS** (reduces network and E): every visitor downloads and parses only the rules the pages use, not the whole framework or old stylesheet. It runs once per build, so the cost is paid once and the saving repeats on every page view. https://patterns.greensoftware.foundation/development/media-and-code-efficiency/remove-unused-css
- **Scan the final output:** `dist/` includes the JS bundles, so class names that are built into strings there are kept. The safelist covers classes that are assembled at runtime, such as `'btn-' + variant`. Check your own toggled classes and add them, or purged styles will be missing in the browser.
- **Order matters:** purge first, then minify and compress, so those steps work on the smaller file.
- *Not applied:* if the site is a handful of pages with a small hand-written stylesheet, this step adds build complexity for little gain. Skip it there.

hello, in my flask api i return error to client but i always get status 200 even when user not found. how i can return 404 with json message? my code:

```python
from flask import Flask, jsonify

app = Flask(__name__)

USERS = {1: "anna", 2: "ben"}

@app.route("/users/<int:user_id>")
def get_user(user_id):
    name = USERS.get(user_id)
    if name is None:
        return jsonify({"error": "user not found"})
    return jsonify({"id": user_id, "name": name})
```

Flask sends status 200 by default. To change it, return a tuple of `(response, status_code)`:

```python
@app.route("/users/<int:user_id>")
def get_user(user_id):
    name = USERS.get(user_id)
    if name is None:
        return jsonify({"error": "user not found"}), 404
    return jsonify({"id": user_id, "name": name})
```

Now the client gets HTTP 404 with the JSON body `{"error": "user not found"}`.

You can also use `abort(404)` and one handler for all 404 errors, so the format is the same everywhere:

```python
from flask import abort

@app.errorhandler(404)
def not_found(e):
    return jsonify({"error": "not found"}), 404

@app.route("/users/<int:user_id>")
def get_user(user_id):
    name = USERS.get(user_id)
    if name is None:
        abort(404)
    return jsonify({"id": user_id, "name": name})
```

Note: with this handler, every 404 (also unknown URLs) returns the same generic message. If you want a specific message like "user not found", use `abort(404, description="user not found")` and return `e.description` in the handler.

