```go
package members

import (
	"database/sql"
	"encoding/json"
	"net/http"
	"strconv"
)

const (
	defaultLimit = 50
	maxLimit     = 200
)

// Only the columns the response needs. No SELECT *.
const listMembersSQL = `
SELECT id, display_name, email, COALESCE(avatar_url, ''), role
FROM users
WHERE team_id = $1
  AND deactivated_at IS NULL
  AND id > $2
ORDER BY id
LIMIT $3`

type member struct {
	ID          int64  `json:"id"`
	DisplayName string `json:"display_name"`
	Email       string `json:"email"`
	AvatarURL   string `json:"avatar_url"`
	Role        string `json:"role"`
}

type page struct {
	Members    []member `json:"members"`
	NextCursor *int64   `json:"next_cursor,omitempty"`
}

func ListMembers(db *sql.DB) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		q := r.URL.Query()

		teamID, err := strconv.ParseInt(q.Get("team_id"), 10, 64)
		if err != nil {
			http.Error(w, "invalid team_id", http.StatusBadRequest)
			return
		}

		var after int64
		if s := q.Get("after"); s != "" {
			if after, err = strconv.ParseInt(s, 10, 64); err != nil {
				http.Error(w, "invalid after", http.StatusBadRequest)
				return
			}
		}

		limit := defaultLimit
		if s := q.Get("limit"); s != "" {
			if limit, err = strconv.Atoi(s); err != nil || limit < 1 {
				http.Error(w, "invalid limit", http.StatusBadRequest)
				return
			}
			if limit > maxLimit {
				limit = maxLimit
			}
		}

		rows, err := db.QueryContext(r.Context(), listMembersSQL, teamID, after, limit)
		if err != nil {
			http.Error(w, "internal error", http.StatusInternalServerError)
			return
		}
		defer rows.Close()

		out := page{Members: make([]member, 0, limit)}
		for rows.Next() {
			var m member
			if err := rows.Scan(&m.ID, &m.DisplayName, &m.Email, &m.AvatarURL, &m.Role); err != nil {
				http.Error(w, "internal error", http.StatusInternalServerError)
				return
			}
			out.Members = append(out.Members, m)
		}
		if err := rows.Err(); err != nil {
			http.Error(w, "internal error", http.StatusInternalServerError)
			return
		}

		// A full page means there may be more rows.
		if len(out.Members) == limit {
			last := out.Members[len(out.Members)-1].ID
			out.NextCursor = &last
		}

		w.Header().Set("Content-Type", "application/json")
		_ = json.NewEncoder(w).Encode(out)
	}
}
```

Notes on behavior:

- If the last page has exactly `limit` rows, the client gets one more cursor and then an empty page. That keeps the query simple.
- For speed, `users` should have an index on `(team_id, id)`.

**Green Notes**
- **Named columns instead of `SELECT *`** (reduces E, network): the query reads 5 columns, not the 40+ on `users`. `bio`, `profile_json` and `password_hash` never leave the database. In Green Metrics Tool micro-benchmarks on PostgreSQL, reading rows from a 52-column table with large text columns used about 5.5× to 7× less CPU energy when 10 needed columns were named instead of using `SELECT *`. The saving grows with the size of the skipped columns. It also keeps `password_hash` out of the Go process. https://patterns.greensoftware.foundation/development/data-handling/reduce-transmitted-data
- **Capped cursor pagination** (reduces E, network): at most 200 rows per request, and the `id > $2` cursor avoids the growing skip cost of `OFFSET`.
- *Not applied:* response caching. Member lists change when people join or leave, and a stale list could show deactivated users.

