package com.acme.logs;

import java.io.BufferedReader;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.HashMap;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public final class SlowRequestReport {

    private static final Pattern LINE = Pattern.compile(
        "^(\\d{4}-\\d{2}-\\d{2}T[\\d:.]+Z) (\\w+) \\[([^\\]]+)\\] "
        + "(GET|POST|PUT|DELETE) (\\S+) -> (\\d{3}) in (\\d+)ms$");

    private static final long SLOW_MS = 500;

    public static Map<String, Long> countSlowByPath(Path file) throws IOException {
        Map<String, Long> counts = new HashMap<>();
        try (BufferedReader in = Files.newBufferedReader(file, StandardCharsets.UTF_8)) {
            Matcher m = LINE.matcher("");
            String line;
            while ((line = in.readLine()) != null) {
                if (!m.reset(line).matches()) {
                    continue;
                }
                if (Long.parseLong(m.group(7)) < SLOW_MS) {
                    continue;
                }
                counts.merge(m.group(5), 1L, Long::sum);
            }
        }
        return counts;
    }

    public static void main(String[] args) throws IOException {
        countSlowByPath(Path.of(args[0])).entrySet().stream()
            .sorted(Map.Entry.<String, Long>comparingByValue().reversed())
            .limit(20)
            .forEach(e -> System.out.println(e.getValue() + "\t" + e.getKey()));
    }
}
