RULE_RE = re.compile(r'([^{}]+)\{([^{}]*)\}')
TOKEN_RE = re.compile(r'\.([A-Za-z_][\w-]*)')


def used_classes(site):
    used = set()
    for page in Path(site).rglob("*.html"):
        for m in CLASS_RE.finditer(page.read_text()):
            used.update(m.group(1).split())
    return used


def selector_used(sel, used):
    sel = sel.strip()
    if sel.startswith("@") or sel.startswith(":root") or sel.startswith("html") or sel.startswith("body"):
        return True
    classes = TOKEN_RE.findall(sel)
    if len(classes) == 0:
        return True
    for c in classes:
        if c not in used:
            return False
    return True


def prune(css, used):
    out = []
    for m in RULE_RE.finditer(css):
        keep = [s.strip() for s in m.group(1).split(",") if selector_used(s, used)]
        if keep:
            out.append(",".join(keep) + "{" + m.group(2).strip() + "}")
    return "\n".join(out)


def size_status(kb):
    if kb > 0 and kb <= 50:
        return "ok"
    elif kb > 50 and kb <= 150:
        return "warn"
    else:
        return "fail"


def main(site):
    used = used_classes(site)
    worst = 0
    for css in Path(site).glob("css/app*.css"):
        before = css.stat().st_size
        css.write_text(prune(css.read_text(), used))
        after = css.stat().st_size
        status = size_status(after / 1024)
        print(css.name, before, "->", after, status)
        if status == "fail":
            worst = 1
    return worst


if __name__ == "__main__":
    sys.exit(main(sys.argv[1]))
```

```rust
/// Linear interpolation of (xs, ys) at every query time.
/// `xs` must be sorted in strictly increasing order and not empty.
/// Queries outside the range get the first or last value. NaN gives NaN.
pub fn interp_many(xs: &[f64], ys: &[f64], queries: &[f64]) -> Vec<f64> {
    assert_eq!(xs.len(), ys.len(), "xs and ys must have the same length");
    assert!(!xs.is_empty(), "need at least one point");
    let last = xs.len() - 1;

    queries
        .iter()
        .map(|&q| {
            if q.is_nan() {
                return f64::NAN;
            }
            if q <= xs[0] {
                return ys[0];
            }
            if q >= xs[last] {
                return ys[last];
            }
            // First index with xs[i] >= q. Here 1 <= i <= last.
            let i = xs.partition_point(|&x| x < q);
            let (x0, x1) = (xs[i - 1], xs[i]);
            let t = (q - x0) / (x1 - x0);
            ys[i - 1] + t * (ys[i] - ys[i - 1])
        })
        .collect()
}

fn main() {
    let xs = [0.0, 10.0, 20.0, 40.0];
    let ys = [1.0, 3.0, 2.0, 6.0];
    let out = interp_many(&xs, &ys, &[-5.0, 0.0, 5.0, 15.0, 30.0, 50.0]);
    println!("{:?}", out); // [1.0, 1.0, 2.0, 2.5, 4.0, 6.0]
}
```

**Green Notes**
- **Binary search with `partition_point`** (reduces E): each query costs O(log n) steps instead of a scan over all `xs`. For 2 million queries on 500k points, that is about 19 comparisons per query instead of up to 500k.
- **Output allocated once:** `map` + `collect` on a slice iterator knows the length, so the result `Vec` is allocated one time.
- *Not applied:* if your queries are also sorted, a single two-pointer walk over both arrays would be O(n + m). It is more code and breaks when the order is not guaranteed, so I kept the binary search.
- The code assumes strictly increasing `xs`. With duplicate timestamps, `x1 - x0` can be zero and you get NaN, so remove duplicates first.

Keep the newest entry at the front of an `ArrayDeque`. Adding at the front is O(1). `ArrayList.add(0, x)` would shift every element on each deploy.

```java
import java.time.Instant;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import java.util.Optional;

public final class DeployHistory {

    public record Deployment(String service, String version, Instant at, boolean success) {}

    private final int capacity;
    private final ArrayDeque<Deployment> items;

    public DeployHistory(int capacity) {
        if (capacity <= 0) {
            throw new IllegalArgumentException("capacity must be > 0");
        }
        this.capacity = capacity;
        this.items = new ArrayDeque<>(capacity);
    }

    /** Called from many webhook threads, so access is synchronized. */
    public synchronized void add(Deployment d) {
        if (items.size() == capacity) {
            items.removeLast();   // drop the oldest
        }
        items.addFirst(d);        // newest first
    }

    /** Newest first, at most n entries. */
    public synchronized List<Deployment> recent(int n) {
        List<Deployment> out = new ArrayList<>(Math.max(0, Math.min(n, items.size())));
        Iterator<Deployment> it = items.iterator();
        while (it.hasNext() && out.size() < n) {
            out.add(it.next());
        }
        return out;
    }

    /** Newest successful deploy of one service, for rollback. */
    public synchronized Optional<Deployment> lastSuccessful(String service) {
        for (Deployment d : items) {
            if (d.success() && d.service().equals(service)) {
                return Optional.of(d);
            }
        }
        return Optional.empty();
    }
}
```

`recent()` returns a copy, so the status page never reads the deque while another thread changes it. `lastSuccessful()` stops at the first match, because the newest entries come first.

**Green Notes**
- **`ArrayDeque.addFirst` instead of `list.add(0, x)`** (reduces E): front insertion costs O(1) and does not move the other entries. The deque iterates newest first, so you never need to reverse the list.
- **Fixed capacity with `removeLast()`** (reduces E, M): memory stays bounded and old entries are dropped right away.
- **Early exit in `lastSuccessful`**: it scans only as far as the first match, not the whole history.
- *Not applied:* a lock-free queue. With 50 entries and short critical sections, `synchronized` is simpler and the contention is low.

Hi, can you check my code pls? Is for the dashboard of our image classifier, we log every prediction and show it in a table. The page is very slow when I type in the search box, we have around 20000 rows. I dont know why.

```javascript
// predictions.js
const tbody = document.querySelector('#pred-body');
const searchInput = document.querySelector('#search');
let allPredictions = [];

async function loadPredictions() {
  const res = await fetch('/api/predictions?limit=20000');
  allPredictions = await res.json();
  render(allPredictions, '');
}

function highlight(text, term) {
  if (!term) return text;
  const re = new RegExp('(' + term + ')', 'gi');
  return text.replace(re, '<mark>$1</mark>');
}

function render(rows, term) {
  tbody.innerHTML = '';
  rows.forEach(r => {
    tbody.innerHTML += `<tr>
      <td>${r.id}</td>
      <td>${highlight(r.filename, term)}</td>
      <td>${highlight(r.label, term)}</td>
      <td>${(r.confidence * 100).toFixed(1)}%</td>
      <td>${r.latencyMs} ms</td>
    </tr>`;
  });
}

searchInput.addEventListener('input', () => {
  const term = searchInput.value.trim();
  const filtered = allPredictions.filter(r => {
    const re = new RegExp(term, 'i');
    return re.test(r.filename) || re.test(r.label);
  });
  render(filtered, term);
});

loadPredictions();
```

**Workload:** web (browser-side dashboard, runs on every keystroke)

#### [Bug] Search term is used as a raw regex
- **Where:** `highlight` and the `input` handler
- **Issue:** if someone types `(` or `[`, `new RegExp` throws a `SyntaxError` and the table stops updating. A `.` matches every character, so the filter shows wrong rows.
- **Fix:** escape the term before you build the regex (see `escapeRegExp` below).

#### [Security] Prediction data goes into `innerHTML`
- **Where:** `render`
- **Issue:** `filename` and `label` are inserted as HTML. A file name like `<img src=x onerror=...>` runs script in the page of everyone who opens the dashboard.
- **Fix:** build cells with `textContent` and create `<mark>` elements instead of HTML strings.

#### [High] All 20000 rows are in the DOM, and the table is rebuilt with `+=`
- **Where:** `render`
- **Issue:** `tbody.innerHTML += ...` serializes the whole table and parses it again for every row. The work grows with the square of the row count. The browser also keeps tens of thousands of nodes alive, and the user can only see about 30 of them.
- **Fix:** show one page of rows (for example 100) and add a "Show more" button. Create the rows in a `DocumentFragment` and append them once.
- **Impact:** reduces E on the client per keystroke, because layout and style work follow the number of DOM nodes. It also lowers memory use.

#### [High] Regex is built again for every row
- **Where:** the `filter` callback (once per row) and `highlight` (twice per row)
- **Issue:** the term does not change during one keystroke, but the code builds the same pattern about 60000 times for 20000 rows.
- **Fix:** build one regex per keystroke and pass it to the filter and to the highlighter. Use one regex with the `i` flag and one capture group. Without the `g` flag, `.test()` has no `lastIndex` state, so it is safe to reuse. `split` with a capture group gives the matches at odd positions.
- **Impact:** reduces E per keystroke, from one regex build per row to one in total.

#### [Medium] No debounce on the `input` event
- **Where:** `searchInput` listener
- **Issue:** every key press filters 20000 rows and re-renders, even when the user types fast.
- **Fix:** wait about 150 ms after the last key press. This changes timing a little: the table updates when typing pauses.

Fixed version (add `<button id="more" hidden>Show more</button>` below the table):

```javascript
// predictions.js
const PAGE_SIZE = 100;
const tbody = document.querySelector('#pred-body');
const searchInput = document.querySelector('#search');
const moreBtn = document.querySelector('#more');

let allPredictions = [];
let currentRows = [];
let currentRe = null;
let shown = 0;
let timer;

function escapeRegExp(s) {
  return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function makeMatcher(term) {
  return term ? new RegExp('(' + escapeRegExp(term) + ')', 'i') : null;
}

function setCellText(cell, text, re) {
  if (!re) {
    cell.textContent = text;
    return;
  }
  text.split(re).forEach((part, i) => {
    if (i % 2 === 1) {
      const mark = document.createElement('mark');
      mark.textContent = part;
      cell.append(mark);
    } else if (part) {
      cell.append(part);
    }
  });
}

function createRow(r, re) {
  const tr = document.createElement('tr');
  const values = [
    r.id,
    r.filename,
    r.label,
    `${(r.confidence * 100).toFixed(1)}%`,
    `${r.latencyMs} ms`,
  ];
  values.forEach((v, i) => {
    const td = document.createElement('td');
    if (i === 1 || i === 2) setCellText(td, String(v), re);
    else td.textContent = v;
    tr.append(td);
  });
  return tr;
}

function renderMore() {
  const frag = document.createDocumentFragment();
  const end = Math.min(shown + PAGE_SIZE, currentRows.length);
  for (; shown < end; shown++) {
    frag.append(createRow(currentRows[shown], currentRe));
  }
  tbody.append(frag);
  moreBtn.hidden = shown >= currentRows.length;
}

function applyFilter(term) {
  currentRe = makeMatcher(term);
  currentRows = currentRe
    ? allPredictions.filter(r => currentRe.test(r.filename) || currentRe.test(r.label))
    : allPredictions;
  shown = 0;
  tbody.replaceChildren();
  renderMore();
}

async function loadPredictions() {
  const res = await fetch('/api/predictions?limit=20000');
  allPredictions = await res.json();
  applyFilter('');
}

searchInput.addEventListener('input', () => {
  clearTimeout(timer);
  timer = setTimeout(() => applyFilter(searchInput.value.trim()), 150);
});
moreBtn.addEventListener('click', renderMore);

loadPredictions();
```

**Already good:** the data is fetched once and filtered in memory, so typing does not cause network requests.

