      });

    function render(list) {
      var box = document.getElementById('results');
      box.innerHTML = '';
      for (var i = 0; i < list.length; i++) {
        var p = list[i];
        var html = '<div class="row">';
        html += '<img src="/thumbs/' + p.id + '.jpg" width="64" height="64">';
        html += '<span class="label">' + p.label + '</span>';
        html += '<span>' + (p.conf * 100).toFixed(1) + '%</span>';
        html += '<div class="bars">';
        for (var j = 0; j < p.top5.length; j++) {
          html += '<div class="bar" title="' + p.top5[j].label + '" style="width:' + (p.top5[j].p * 100) + '%"></div>';
        }
        html += '</div></div>';
        box.innerHTML += html;
      }
    }

    document.getElementById('filter').oninput = function () {
      var q = this.value.toLowerCase();
