        return p.label.toLowerCase().indexOf(q) !== -1;
      }));
    };
  </script>
</body>
</html>
```

There are two problems.

1. The page puts all 8000 rows into the DOM at once. Each row has about 10 elements, so that is tens of thousands of nodes. The browser has to keep them all in memory and re-layout them.
2. `box.innerHTML += html` is inside the loop. Every pass re-parses everything that is already in the box, so the work grows with the square of the row count. That is the freeze.

The fix is to show one page of rows at a time and write the HTML once.

```html
<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8">
  <title>Classifier results</title>
  <style>
    .row { display: flex; align-items: center; gap: 12px; padding: 4px; border-bottom: 1px solid #ddd; }
    .label { width: 160px; font-weight: bold; }
    .bars { width: 200px; }
    .bar { height: 6px; background: #4a90d9; margin: 1px 0; }
  </style>
</head>
<body>
  <h2>Batch results</h2>
  <input id="filter" placeholder="filter by label">
  <div>
    <button id="prev">Previous</button>
    <span id="info"></span>
    <button id="next">Next</button>
  </div>
  <div id="results"></div>

  <script>
    var PAGE_SIZE = 50;
    var allResults = [];
    var shown = [];
    var page = 0;

    function esc(s) {
      return String(s)
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;');
    }

    function rowHtml(p) {
      var bars = p.top5.map(function (t) {
        return '<div class="bar" title="' + esc(t.label) + '" style="width:' + (t.p * 100) + '%"></div>';
      }).join('');
      return '<div class="row">' +
        '<img src="/thumbs/' + encodeURIComponent(p.id) + '.jpg" width="64" height="64">' +
        '<span class="label">' + esc(p.label) + '</span>' +
        '<span>' + (p.conf * 100).toFixed(1) + '%</span>' +
        '<div class="bars">' + bars + '</div></div>';
    }

    function render() {
      var pages = Math.max(1, Math.ceil(shown.length / PAGE_SIZE));
      page = Math.min(page, pages - 1);
      var slice = shown.slice(page * PAGE_SIZE, (page + 1) * PAGE_SIZE);
      document.getElementById('results').innerHTML = slice.map(rowHtml).join('');
      document.getElementById('info').textContent =
        'Page ' + (page + 1) + ' of ' + pages + ' (' + shown.length + ' results)';
      document.getElementById('prev').disabled = page === 0;
      document.getElementById('next').disabled = page >= pages - 1;
    }

    fetch('/api/batch/latest')
      .then(function (r) { return r.json(); })
      .then(function (data) {
        allResults = data;
        shown = data;
        render();
      });

    document.getElementById('filter').oninput = function () {
      var q = this.value.toLowerCase();
      shown = allResults.filter(function (p) {
        return p.label.toLowerCase().indexOf(q) !== -1;
      });
      page = 0;
      render();
    };
    document.getElementById('prev').onclick = function () { page--; render(); };
    document.getElementById('next').onclick = function () { page++; render(); };
  </script>
</body>
</html>
```

**Green Notes**
- **Small DOM with pagination** (reduces E): at most 50 rows (about 500 elements) exist at any time, not 8000 rows. Style, layout and memory work now depend on the page size, not on the batch size. Pattern: https://patterns.greensoftware.foundation/development/web-performance/avoid-excessive-dom-size
- **One `innerHTML` write instead of one per row** (reduces E): the old `+=` re-parsed all existing rows on every pass. Now the HTML is built with `map` and `join` and parsed once.
- **Behavior changes:** the filter still searches all results, but only one page is visible. The browser's Ctrl+F can no longer find rows on other pages. If your team needs to scan thousands of rows in one view, use a virtual list instead.
- **Bug fixed:** labels were put into the HTML without escaping. A label like `<b>` would break the layout, and a label from untrusted input could inject script. The code now escapes them.

We switched our API gateway to max compression to save bandwidth. CPU on the gateway went up a lot. Is this config ok?

```nginx
brotli on;
brotli_comp_level 11;
brotli_types application/json text/plain text/css application/javascript image/png image/jpeg;

gzip on;
gzip_comp_level 9;
gzip_types application/json text/plain text/css application/javascript image/png image/jpeg;
```

**Workload:** cloud backend (API gateway, every response)

#### [High] Brotli level 11 on dynamic responses
- **Where:** `brotli_comp_level 11;`
- **Issue:** level 11 is meant for static files compressed once at build time. Here it runs on every API response. In Green Metrics Tool measurements, compressing 100 MB with brotli at its default quality 11 took about 45× the energy of gzip ([measurements](https://metrics.green-coding.io/compare-simple.html?ids=fb08d3c3-ba41-4f0f-85fd-0b6c34e6c39b,f1479db0-c453-4aaa-9116-e137621fad07,8e93a8d2-60b0-4831-905b-764b68257bc7)). The few extra percent of compression don't make up for that on a response that is sent once.
- **Fix:** level 4-5 for dynamic responses. That keeps most of the size reduction at a fraction of the CPU.
- **Impact:** reduces E on the gateway for every request, and your CPU usage should drop back.

#### [Medium] Images in the compression types
- **Where:** `image/png image/jpeg` in `brotli_types` and `gzip_types`
- **Issue:** PNG and JPEG are already compressed. Compressing them again burns CPU and saves almost nothing.
- **Fix:** list only text formats: JSON, HTML, CSS, JavaScript, SVG, plain text.

#### [Low] gzip level 9
- **Where:** `gzip_comp_level 9;`
- **Issue:** gzip is now only a fallback for clients without brotli, and level 9 gains little over level 5.

```nginx
brotli on;
brotli_comp_level 5;
brotli_min_length 1024;
brotli_types application/json text/plain text/css application/javascript image/svg+xml;

