  animation: promo-scroll 20s linear infinite;
}
.promo-bar:hover #promo-text { animation-play-state: paused; }
@keyframes promo-scroll {
  from { transform: translateX(0); }
  to   { transform: translateX(-100%); }
}
@media (prefers-reduced-motion: reduce) {
  #promo-text { animation: none; padding-left: 0; }
}
```

Then delete the `setInterval` block. The `var promo` and `var x` lines are not needed any more.

#### [Low] Ship the text without motion if it is short
- **Where:** the promo bar
- **Issue:** three short messages may fit on a phone screen without scrolling. A static bar costs nothing.
- **Fix:** if you keep the scroll, the `prefers-reduced-motion` rule above already stops it for users who ask for less motion.

**Already good:** the data is read from one array, so no extra requests are made per product.

hi, i have object detection on a raspberry pi camera (yolo model, onnx runtime node). after the model i do NMS in js. my colleague say it is O(n^2) and we must use some spatial tree or grid, he say its not green. is he right? i dont want to make code more complicated for nothing

```javascript
function iou(a, b) {
  const x1 = Math.max(a.x1, b.x1);
  const y1 = Math.max(a.y1, b.y1);
  const x2 = Math.min(a.x2, b.x2);
  const y2 = Math.min(a.y2, b.y2);
  const inter = Math.max(0, x2 - x1) * Math.max(0, y2 - y1);
  const areaA = (a.x2 - a.x1) * (a.y2 - a.y1);
  const areaB = (b.x2 - b.x1) * (b.y2 - b.y1);
  return inter / (areaA + areaB - inter);
}

function nms(dets, scoreThr = 0.3, iouThr = 0.5) {
  const cand = dets
    .filter(d => d.score >= scoreThr)
    .sort((a, b) => b.score - a.score);
  const keep = [];
  const dead = new Array(cand.length).fill(false);
  for (let i = 0; i < cand.length; i++) {
    if (dead[i]) continue;
    keep.push(cand[i]);
    for (let j = i + 1; j < cand.length; j++) {
      if (!dead[j] && cand[j].cls === cand[i].cls && iou(cand[i], cand[j]) > iouThr) {
        dead[j] = true;
      }
    }
  }
  return keep;
}
```

