package inference

import "math"

type Normalizer struct {
	mean   []float32
	invStd []float32
}

func NewNormalizer(mean, std []float32) *Normalizer {
	inv := make([]float32, len(std))
	for i, s := range std {
		inv[i] = 1 / s
	}
	return &Normalizer{mean: mean, invStd: inv}
}

// Apply normalizes a CHW image in place.
func (n *Normalizer) Apply(pix []float32, hw int) {
	for c := range n.mean {
		m, s := n.mean[c], n.invStd[c]
		plane := pix[c*hw : (c+1)*hw]
		for i := range plane {
			plane[i] = (plane[i] - m) * s
		}
	}
}

// Softmax writes probabilities into out (same length as logits).
func Softmax(logits, out []float32) {
	maxv := logits[0]
	for _, v := range logits[1:] {
		if v > maxv {
			maxv = v
		}
	}
	var sum float32
	for i, v := range logits {
		e := float32(math.Exp(float64(v - maxv)))
		out[i] = e
		sum += e
	}
	inv := 1 / sum
	for i := range out {
		out[i] *= inv
	}
}
