```java
import java.util.OptionalInt;

public final class CampaignParam {
    // 9 digits always fit in an int, so no overflow check is needed
    private static final int MAX_DIGITS = 9;

    private CampaignParam() {}

    public static OptionalInt parseCampaignId(String raw) {
        if (raw == null) {
            return OptionalInt.empty();
        }
        int len = raw.length();
        if (len == 0 || len > MAX_DIGITS) {
            return OptionalInt.empty();
        }
        int value = 0;
        for (int i = 0; i < len; i++) {
            char c = raw.charAt(i);
            if (c < '0' || c > '9') {
                return OptionalInt.empty();
            }
            value = value * 10 + (c - '0');
        }
        return OptionalInt.of(value);
    }
}
