The dashboard table only needs a few small fields, so the query names exactly those columns. It also takes a limit, so one call never loads every failed build. The big log is read by a separate method, only when someone opens one build.

```java
import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.sql.Timestamp;
import java.util.ArrayList;
import java.util.List;
import java.util.Optional;

public class BuildRepository {

    public record BuildSummary(
            long id, String branch, Timestamp startedAt, long durationMs) {}

    private static final String FAILED_SQL =
            "SELECT id, branch, started_at, duration_ms "
            + "FROM builds "
            + "WHERE pipeline = ? AND status = 'failed' "
            + "ORDER BY started_at DESC "
            + "LIMIT ?";

    private static final String LOG_SQL =
            "SELECT log_output FROM builds WHERE id = ?";

    private final Connection conn;

    public BuildRepository(Connection conn) {
        this.conn = conn;
    }

    // For the dashboard table: small columns only.
    public List<BuildSummary> findFailed(String pipeline, int limit) throws SQLException {
        List<BuildSummary> result = new ArrayList<>();
        try (PreparedStatement ps = conn.prepareStatement(FAILED_SQL)) {
            ps.setString(1, pipeline);
            ps.setInt(2, limit);
            try (ResultSet rs = ps.executeQuery()) {
                while (rs.next()) {
                    result.add(new BuildSummary(
                            rs.getLong("id"),
                            rs.getString("branch"),
                            rs.getTimestamp("started_at"),
                            rs.getLong("duration_ms")));
                }
            }
        }
        return result;
    }

    // Only called when a user opens one build.
    public Optional<String> findLog(long buildId) throws SQLException {
        try (PreparedStatement ps = conn.prepareStatement(LOG_SQL)) {
            ps.setLong(1, buildId);
            try (ResultSet rs = ps.executeQuery()) {
                return rs.next() ? Optional.ofNullable(rs.getString(1)) : Optional.empty();
            }
        }
    }
}
```

