This fills in the TODO. It shows 50 devices per page and adds a search box, so the table never holds 3000 rows at once.

```html
<!doctype html>
<html>
<head>
  <meta charset="utf-8">
  <title>BLE Gateway - Devices</title>
  <style>
    body { font-family: sans-serif; margin: 1rem; }
    table { border-collapse: collapse; width: 100%; }
    td, th { border-bottom: 1px solid #ddd; padding: 4px 8px; text-align: left; }
    .bar { display: flex; gap: .5rem; align-items: center; margin: .5rem 0; }
  </style>
</head>
<body>
  <h1>Paired sensors</h1>
  <div class="bar">
    <input id="search" type="search" placeholder="Search name or MAC">
    <button id="prev" type="button">Prev</button>
    <span id="pageinfo"></span>
    <button id="next" type="button">Next</button>
  </div>
  <table id="devices">
    <thead><tr><th>Name</th><th>MAC</th><th>Battery</th><th>RSSI</th><th>Last seen</th></tr></thead>
    <tbody></tbody>
  </table>
  <script>
    const PAGE_SIZE = 50;
    let devices = [];
    let filtered = [];
    let page = 0;

    const tbody = document.querySelector('#devices tbody');
    const search = document.getElementById('search');
    const prev = document.getElementById('prev');
    const next = document.getElementById('next');
    const pageinfo = document.getElementById('pageinfo');

    function render() {
      const pages = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
      page = Math.min(page, pages - 1);
      const start = page * PAGE_SIZE;

      const frag = document.createDocumentFragment();
      for (const d of filtered.slice(start, start + PAGE_SIZE)) {
        const tr = document.createElement('tr');
        const cells = [d.name, d.mac, d.battery + '%', d.rssi + ' dBm', d.lastSeen];
        for (const text of cells) {
          const td = document.createElement('td');
          td.textContent = text;
          tr.appendChild(td);
        }
        frag.appendChild(tr);
      }
      tbody.replaceChildren(frag);

      pageinfo.textContent = 'Page ' + (page + 1) + ' of ' + pages +
        ' (' + filtered.length + ' devices)';
      prev.disabled = page === 0;
      next.disabled = page >= pages - 1;
    }

    function applyFilter() {
      const q = search.value.trim().toLowerCase();
      filtered = q
        ? devices.filter(d => d.name.toLowerCase().includes(q) ||
                              d.mac.toLowerCase().includes(q))
        : devices;
      page = 0;
      render();
    }

    prev.addEventListener('click', () => { page--; render(); });
    next.addEventListener('click', () => { page++; render(); });
    search.addEventListener('input', applyFilter);

    async function load() {
      const res = await fetch('/api/devices');
      devices = await res.json();
      applyFilter();
    }
    load();
  </script>
</body>
</html>
```

**Green Notes**
- **Small DOM** (reduces client E): the table holds at most 50 rows instead of 3000 rows with 5 cells each. The browser builds, styles and lays out far fewer nodes. This matters on a low-power tablet.
  https://patterns.greensoftware.foundation/development/web-performance/avoid-excessive-dom-size
- **One DOM write per page change**: rows are built in a `DocumentFragment` and swapped in with `replaceChildren`. This gives one reflow, not one per row. `textContent` also avoids HTML parsing and escaping bugs.
- *Not applied:* a virtual scroller. For a 3000-row list with search, pagination is simpler and enough. If you need continuous scrolling, add virtualization then.

The API still sends all 3000 devices once. If the payload is large, add `?page=` and `?q=` on the server too.

