Nothing is wrong with your code. The `src` folder is just not meant to be shipped as it is. It holds unminified source, and the browser has to fetch `chart.js` and your helper as separate files. A small build step fixes both. It bundles and minifies the JS and CSS, and it also writes gzip copies once, so the gateway doesn't compress anything while serving.

Install esbuild on your dev machine, not on the device: `npm install --save-dev esbuild`

```javascript
// build.mjs
import { build } from 'esbuild';
import { cp, mkdir, readFile, rm, writeFile } from 'node:fs/promises';
import { gzipSync } from 'node:zlib';

await rm('dist', { recursive: true, force: true });
await mkdir('dist', { recursive: true });

await build({
  entryPoints: { app: 'src/app.js', style: 'src/style.css' },
  bundle: true,            // chart.js + helper end up in one file
  minify: true,
  target: 'es2019',        // older browsers on old tablets still work
  sourcemap: false,        // do not ship source maps to the device
  legalComments: 'none',
  define: { 'process.env.NODE_ENV': '"production"' },
  outdir: 'dist',
});

await cp('src/index.html', 'dist/index.html');

// Compress once per release. Keep the plain files as a fallback.
for (const file of ['app.js', 'style.css', 'index.html']) {
  const data = await readFile(`dist/${file}`);
  await writeFile(`dist/${file}.gz`, gzipSync(data, { level: 9 }));
}

