```go
package main

import (
	_ "embed"
	"encoding/json"
	"hash/fnv"
	"math"
	"net/http"
	"strings"
	"sync"
)

const dim = 256

//go:generate esbuild web/playground.js --minify --outfile=web/playground.min.js

//go:embed web/playground.min.js
var playgroundJS []byte

const page = `<!doctype html>
<html><body>
<textarea id="t"></textarea>
<input id="l" value="billing, bug, feature">
<button id="go">Classify</button>
<pre id="out"></pre>
<script src="/playground.js"></script>
</body></html>`

func embed(text string) []float32 {
	v := make([]float32, dim)
	t := strings.ToLower(text)
	for i := 0; i+3 <= len(t); i++ {
		h := fnv.New32a()
		h.Write([]byte(t[i : i+3]))
		v[h.Sum32()%dim] += 1
	}
	var norm float64
	for _, x := range v {
		norm += float64(x) * float64(x)
	}
	if norm > 0 {
		n := float32(math.Sqrt(norm))
		for i := range v {
			v[i] /= n
		}
	}
	return v
}

// Label vectors depend only on the label text, and requests reuse a small
// set of labels. The cache is bounded because labels come from the client.
// Cached slices are shared: callers must only read them.
const maxCachedLabels = 1024

var (
	labelMu    sync.RWMutex
	labelCache = map[string][]float32{}
)

func labelVec(label string) []float32 {
	labelMu.RLock()
	v, ok := labelCache[label]
	labelMu.RUnlock()
	if ok {
		return v
	}
	v = embed(label)
	labelMu.Lock()
	if len(labelCache) < maxCachedLabels {
		labelCache[label] = v
	}
	labelMu.Unlock()
	return v
}

func dot(a, b []float32) float64 {
	var s float64
	for i := range a {
		s += float64(a[i]) * float64(b[i])
	}
	return s
}

type request struct {
	Text   string   `json:"text"`
	Labels []string `json:"labels"`
}

type response struct {
	Best   string             `json:"best"`
	Scores map[string]float64 `json:"scores"`
}

func classify(w http.ResponseWriter, r *http.Request) {
	var in request
	if err := json.NewDecoder(r.Body).Decode(&in); err != nil {
		http.Error(w, "bad json", http.StatusBadRequest)
		return
	}
	tv := embed(in.Text)
	out := response{Scores: map[string]float64{}}
	best := math.Inf(-1)
	for _, l := range in.Labels {
		s := dot(tv, labelVec(l))
		out.Scores[l] = s
		if s > best {
			best = s
			out.Best = l
		}
	}
	json.NewEncoder(w).Encode(out)
}

func main() {
	http.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "text/html; charset=utf-8")
		w.Write([]byte(page))
	})
	http.HandleFunc("/playground.js", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "text/javascript; charset=utf-8")
		w.Write(playgroundJS)
	})
	http.HandleFunc("/classify", classify)
	http.ListenAndServe(":8080", nil)
}
```

