        f"<body><h1>Simple pricing</h1><ul>{rows}</ul>"
        "<script src='/app.js'></script></body></html>"
    )


def guess_type(path):
    p = path.lower()
    if p.endswith(".html") or p.endswith(".htm"):
        return "text/html; charset=utf-8"
    elif p.endswith(".css"):
        return "text/css"
    elif p.endswith(".js") or p.endswith(".mjs"):
        return "text/javascript"
    elif p.endswith(".json"):
        return "application/json"
    elif p.endswith(".svg"):
        return "image/svg+xml"
    elif p.endswith(".png"):
        return "image/png"
    elif p.endswith(".jpg") or p.endswith(".jpeg"):
        return "image/jpeg"
    elif p.endswith(".webp"):
        return "image/webp"
    elif p.endswith(".avif"):
        return "image/avif"
    elif p.endswith(".woff2"):
        return "font/woff2"
    else:
        return "application/octet-stream"


def app(environ, start_response):
    path = environ.get("PATH_INFO", "/")
    if path == "/":
        body = render_home().encode("utf-8")
        name = "index.html"
    else:
        full = os.path.join(STATIC_DIR, path.lstrip("/"))
        if not os.path.isfile(full):
            start_response("404 Not Found", [("Content-Type", "text/plain")])
            return [b"not found"]
        with open(full, "rb") as f:
            body = f.read()
        name = full

    headers = [("Content-Type", guess_type(name))]
    if "gzip" in environ.get("HTTP_ACCEPT_ENCODING", ""):
        body = gzip.compress(body, 9)
        headers.append(("Content-Encoding", "gzip"))
    headers.append(("Content-Length", str(len(body))))
    start_response("200 OK", headers)
    return [body]


