```go
package logdigest

import (
    "fmt"
    "strings"
    "time"
)

type Entry struct {
    Time    time.Time
    Level   string
    Service string
    Message string
}

var ranks = map[string]int{"DEBUG": 0, "INFO": 1, "WARN": 2, "ERROR": 3}

func ParseLine(line string) (Entry, bool) {
    parts := strings.SplitN(line, "|", 4)
    if len(parts) != 4 {
        return Entry{}, false
    }
    t, err := time.Parse(time.RFC3339, parts[0])
    if err != nil {
        return Entry{}, false
    }
    return Entry{Time: t, Level: parts[1], Service: parts[2], Message: strings.TrimSpace(parts[3])}, true
}

func BuildDigest(lines []string, minLevel string) string {
    digest := ""
    count := 0
    for _, line := range lines {
        e, ok := ParseLine(line)
        if !ok {
            continue
        }
        if ranks[e.Level] < ranks[minLevel] {
            continue
        }
        digest += e.Time.UTC().Format(time.RFC3339) + " [" + e.Level + "] " + e.Service + ": " + e.Message + "\n"
        count++
    }
    digest += fmt.Sprintf("-- %d entries --\n", count)
    return digest
}
