    const label = document.getElementById("label");
    const text = { running: "Running", done: "Done", failed: "Failed", unknown: "Status not available" };

    function setState(state) {
      if (!(state in text)) state = "unknown";
      job.dataset.state = state;
      label.textContent = text[state];
    }

