hello, i have text classifier service (small bert, on CPU) and the tokenizing part before the model is slower than i expect. We get many requests with batch of reviews, and I think many words are not in my vocab because users write with slang and typos. Can you clean up and make it faster please? Sorry for my english.

```python
import numpy as np

STOPWORDS = ["the", "a", "an", "and", "or", "of", "to", "in", "is", "it",
             "this", "that", "for", "on", "with", "as", "was", "are", "be", "by",
             "at", "from", "but", "not", "have", "has", "had", "were", "been", "will"]

PAD_ID = 0
UNK_ID = 1


def encode(text, vocab, max_len=64):
    ids = []
    for tok in text.lower().split():
        tok = tok.strip(".,!?;:\"'()")
        if tok in STOPWORDS:
            continue
        try:
            ids.append(vocab[tok])
        except KeyError:
            ids.append(UNK_ID)
        if len(ids) >= max_len:
            break
    ids += [PAD_ID] * (max_len - len(ids))
    return ids


def encode_batch(texts, vocab, max_len=64):
    rows = [encode(t, vocab, max_len) for t in texts]
    return np.array(rows, dtype=np.int64)
