- rows older than 90 days are dropped
- amounts are converted to EUR cents
- unknown currencies must be reported, not silently dropped

Before I hand this to the team, I want to know if there are loop-invariant things I forgot to move out of the loop. Anything else you would change for efficiency? Please only change what is worth changing.

```javascript
'use strict';

const RATES = new Map([
  ['EUR', 1],
  ['USD', 0.92],
  ['GBP', 1.17],
  ['CHF', 1.04],
]);
const SKU_RE = /^([A-Z]{2,4})-(\d{4,8})(?:-([A-Z0-9]+))?$/;
const DAY_MS = 24 * 60 * 60 * 1000;

function normalizeRows(rows, runDate) {
  const cutoff = Date.parse(runDate) - 90 * DAY_MS;
  const out = [];
  const unknown = new Map();

  for (let i = 0; i < rows.length; i++) {
    const row = rows[i];
    const ts = Date.parse(row.created_at);
    if (ts < cutoff) continue;

    const rate = RATES.get(row.currency);
    if (rate === undefined) {
      unknown.set(row.currency, (unknown.get(row.currency) || 0) + 1);
      continue;
    }

    const m = SKU_RE.exec(row.sku);
    if (m === null) continue;

    out.push({
      orderId: row.order_id,
      brand: m[1],
      item: Number(m[2]),
      variant: m[3] || null,
      amountCents: Math.round(row.amount * rate * 100),
      createdAt: ts,
    });
  }

  return { rows: out, unknown };
}

module.exports = { normalizeRows };
