Instrument log summarizer for our spectrometer runs. Piped from `zcat`, files are a few million lines. Diff only please.

```go
package main

import (
	"bufio"
	"fmt"
	"os"
	"regexp"
	"strconv"

	. "math"
)

func parseSample(line string) (t float64, v float64, ok bool) {
	skip := regexp.MustCompile(`^\s*(#|$)`)
	if skip.MatchString(line) {
		return 0, 0, false
	}
	re := regexp.MustCompile(`^t=([0-9.]+)s\s+ch3\s+v=(-?[0-9.]+(?:[eE][-+]?[0-9]+)?)`)
	m := re.FindStringSubmatch(line)
	if m == nil {
		return 0, 0, false
	}
	t, _ = strconv.ParseFloat(m[1], 64)
	v, _ = strconv.ParseFloat(m[2], 64)
	return t, v, true
}

func main() {
	sc := bufio.NewScanner(os.Stdin)
	var n int
	var sum, sq float64
	for sc.Scan() {
		_, v, ok := parseSample(sc.Text())
		if !ok || IsNaN(v) {
			continue
		}
		n++
		sum += v
		sq += v * v
	}
	if n == 0 {
		fmt.Println("no samples")
		return
	}
	mean := sum / float64(n)
	fmt.Printf("n=%d mean=%.6g rms=%.6g\n", n, mean, Sqrt(sq/float64(n)))
}
