const { publish } = require('./mqtt');

function summarizeWindow(samples) {
  let min = Infinity;
  let max = -Infinity;
  let sum = 0;
  let n = 0;
  for (let i = 0; i < samples.length; i++) {
    const v = samples[i];
    if (v === null || Number.isNaN(v)) continue;
    if (v < min) min = v;
    if (v > max) max = v;
    sum += v;
    n++;
  }
  if (n === 0) return null;
  return { min, max, mean: sum / n, n };
}

function onTick(sensorId, ring) {
  const s = summarizeWindow(ring.snapshot());
  if (s) publish(`gw/${sensorId}/stats`, JSON.stringify(s));
}
